from math import comb
total = comb(50, 5) * comb(12, 2)
tiers = []
for m in [5, 4, 3, 2, 1]:
    for s in [2, 1, 0]:
        if m == 1 and s != 2:
            continue
        if m == 2 and s == 2:
            pass
        count = comb(5, m) * comb(45, 5 - m) * comb(2, s) * comb(10, 2 - s)
        tiers.append((str(m) + ' + ' + str(s) + ' stars', count))
for name, count in tiers:
    print(name + ': 1 in ' + str(round(total / count)))
print('prize tiers:', len(tiers))

import random
random.seed(20261028)
draws = []
for _ in range(200):
    draws.append((sorted(random.sample(range(1, 51), 5)), sorted(random.sample(range(1, 13), 2))))
last_main = {}
last_star = {}
for i, (main, stars) in enumerate(draws):
    for n in main:
        last_main[n] = i
    for n in stars:
        last_star[n] = i
absence_main = sorted(((len(draws) - 1 - last_main.get(n, -1), n) for n in range(1, 51)), reverse=True)
absence_star = sorted(((len(draws) - 1 - last_star.get(n, -1), n) for n in range(1, 13)), reverse=True)
print('SIMULATED draws:', len(draws))
print('most overdue main numbers (gap, number):', absence_main[:5])
print('most overdue Lucky Star (gap, number):', absence_star[:1])

